        FfiConverterTypeLndConfig_lower(config),$0
    )
}
    self.init(unsafeFromRawPointer: pointer)
}

    deinit {
        guard let pointer = pointer else {
            return
        }

        try! rustCall { uniffi_lni_fn_free_lndnode(pointer, $0) }
    }




